<template>
  <div class="resend-verify">
    <q-btn
      flat
      :loading="loading"
      :label="$t('resend_email')"
      class="resend-btn"
      @click="resendVerifyEmail"
      :disable="btn_disable || email == ''"
    >
      <template v-slot:loading>
        <q-spinner-dots class="on-left" size="16px" />
        {{ $t('resend_email') }}
      </template>
    </q-btn>

    <div v-if="error_message" class="resend-status text-destructive">
      <Icon icon="mdi:alert-circle-outline" class="size-4" />
      <span>{{ error_message }}</span>
    </div>

    <div v-if="success_message" class="resend-status text-success">
      <Icon icon="mdi:check-circle-outline" class="size-4" />
      <span>{{ success_message }}</span>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import { api, getClientAuthorization } from 'pages/APIs';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { encodeQueryData } from 'src/utils/general';
export default defineComponent({
  props: {
    email: {
      type: String,
      default: '',
    },
  },
  setup() {
    return {
      error_message: ref(''),
      success_message: ref(''),
      loading: ref(false),
      btn_disable: ref(false),
    };
  },
  methods: {
    async resendVerifyEmail() {
      try {
        if (!this.email) return;
        this.loading = true;
        this.btn_disable = true;
        this.error_message = '';
        this.success_message = '';
        const data = { email: this.email };
        const querystring = encodeQueryData(data);
        await this.sendEmail(querystring);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.btn_disable = false;
      } finally {
        this.loading = false;
      }
    },

    async sendEmail(querystring: string) {
      let response: any;
      response = await axios.get(
        api.resend_confirmation_email + '?' + querystring,
        {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            Authorization: getClientAuthorization(),
          },
        },
      );

      if (response.data?.hasOwnProperty('success') && response.data.success === false) {
        throw { message: response.data.message };
      }

      if (response.data?.hasOwnProperty('success') && response.data.success === true) {
        this.success_message = response.data.message;
      }
      setTimeout(() => {
        this.btn_disable = false;
      }, 60000);
    },
  },
});
</script>

